@StateFoldFacts.fold_state_as_iter
     : forall (S : Type) (E MN T : Type -> Type) (MT : Monad.Monad T) (IT : Basics.MonadIter T)
         (handle : forall X : Type, E X -> T X) (sample : forall X : Type, MN X -> T X)
         (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (s : S),
       @StateFold.fold_state S E MN T MT IT handle sample A t s =
       @Basics.iter T IT (S * A) (S * PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A)
         (@StateFoldFacts.state_fold_step S E MN T MT handle sample A) (
         s, t)

@StateFoldFacts.fold_run_state
     : forall (S : Type) (E MN T : Type -> Type) (MT : Monad.Monad T) (IT : Basics.MonadIter T)
         (QT : Monad.Eq1 T),
       @Monad.Eq1Equivalence T MT QT ->
       @Monad.MonadLawsE T QT MT ->
       forall (handle : forall X : Type, E X -> T X) (sample : forall X : Type, MN X -> T X),
       @IterationLaws.iteration_uniform T MT IT QT ->
       forall (A : Type) (t : PTreeDefinition.ptree (Sum.sum1 (State.stateE S) E) MN A) (s : S),
       @Monad.eq1 T QT (S * A) (@StateFold.fold_state S E MN T MT IT handle sample A t s)
         (@Fold.fold E MN T MT IT handle sample (S * A) (@State.run_state S E MN A t s))

@ITreeFold.itree_iteration_uniform
     : forall E : Type -> Type,
       @IterationLaws.iteration_uniform (ITreeDefinition.itree E) (@ITreeDefinition.Monad_itree E)
         (@ITreeDefinition.MonadIter_itree E) (@ITreeMonad.Eq1_ITree E)

@ITreeFold.itree_fold_ret
     : forall (E MN F : Type -> Type) (handle : forall X : Type, E X -> ITreeDefinition.itree F X)
         (sample : forall X : Type, MN X -> ITreeDefinition.itree F X)
         (A : Type) (a : A),
       @Eqit.eutt F A A (@eq A)
         (@Fold.fold E MN (ITreeDefinition.itree F) (@ITreeDefinition.Monad_itree F)
            (@ITreeDefinition.MonadIter_itree F) handle sample A
            {|
              PTreeDefinition._observe :=
                @PTreeDefinition.RetF E MN A (PTreeDefinition.ptree E MN A) a
            |})
         {| ITreeDefinition._observe := @ITreeDefinition.RetF F A (ITreeDefinition.itree F A) a |}
